def compute_a_n(N):
    a = {}
    a[1] = 0

    def get_a(n):
        if n in a:
            return a[n]
        if n <= 0:
            return 0 # Should not happen for n>=1

        if n % 2 == 0:
            # n = 2k, k = n/2
            k = n // 2
            result = 2 * get_a(k) + k
        else:
            # n = 2k+1, k = floor(n/2), k+1 = ceil(n/2)
            k = n // 2
            result = get_a(k) + get_a(k + 1) + k

        a[n] = result
        return result

    return get_a(N)

# We need a_2025
a_2025 = compute_a_n(2025)
print(f"a_2025 = {a_2025}")

def solve_an(N):
    # a_n sequence starts with a_1 = 0
    if N < 1:
        return None

    # Initialize DP array/dictionary. We need storage up to N.
    a = {}
    a[1] = 0

    for n in range(2, N + 1):
        if n % 2 == 0:
            # n is even: a_n = 2*a_{n/2} + n/2
            a_n = 2 * a[n // 2] + (n // 2)
        else:
            # n is odd: a_n = a_{floor(n/2)} + a_{ceil(n/2)} + floor(n/2)
            # Since n is odd, n = 2k + 1. floor(n/2) = k, ceil(n/2) = k+1.
            k = n // 2 # floor(n/2)
            # a_{ceil(n/2)} = a_{k+1}
            a_n = a[k] + a[k+1] + k

        a[n] = a_n

    return a[N]

target_N = 2025
result = solve_an(target_N)
print(f"a_{target_N} = {result}")

